template<int N>
struct Factorial {
    // Compile-time recursion
    static constexpr int value = N * Factorial<N - 1>::value;
};

template<>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Computation performed during compilation
static_assert(Factorial<7>::value == 5040);
// Impact: Requires 8 template instantiations.

template<int N>
struct DeepInstantiate {
    // Used to test instantiation depth limits
    using Prev = typename DeepInstantiate<N - 1>::Type;
};

template<>
struct DeepInstantiate<0> {
    using Type = void;
};
// Impact: Compilers limit template depth (e.g., 900) to prevent OOM/hangs.

template<typename T>
struct is_ptr { static constexpr bool value = false; };

template<typename T>
struct is_ptr<T*> { static constexpr bool value = true; };

// Using constexpr if for conditional code generation (C++17)
template<typename T>
void compile_time_branch(T val) {
    if constexpr (is_ptr<T>::value) {
        // This block is only compiled/present if T is a pointer
    } else {
        // This block is only compiled/present otherwise
    }
}
